 private static final Map<String,Spec> BY_ID=Map.copyOf(ALL.stream().collect(java.util.stream.Collectors.toMap(Spec::id,s->s)));
 static Spec get(String id){return id==null?null:BY_ID.get(id);}
 static double chance(int level){return .30+.15*(Math.max(1,Math.min(4,level))-1);}
 static double outgoingCap(double multiplier){return Math.min(1.5,Math.max(1,multiplier));}
 static double defensiveCap(double factor){return Math.max(.5,Math.min(1,factor));}
 static void addDefinitions(Map<String,RareDefinitions.Definition> map){for(var s:ALL)map.put(s.id(),new RareDefinitions.Definition(s.id(),s.title(),4,0,s.cooldown(),s.group(),s.description(),List.of(s.reagent(),Material.ECHO_SHARD,s.reagent(),Material.NETHERITE_SCRAP,Material.AIR,Material.DIAMOND,s.reagent(),Material.AMETHYST_BLOCK,s.reagent())));}
